"""
Generate mythological figures for SE Asia + Central Asia cultures.
13 cultures × 20 figures = 260 figures
"""
import json, os

OUT = "data/figures"
os.makedirs(OUT, exist_ok=True)

def fig(name, ftype, domains, pw, df, sp, mg, ws, rarity, alignment, ab_name, ab_desc, desc):
    return {"name":name,"type":ftype,"domains":domains,
            "stats":{"power":pw,"defense":df,"speed":sp,"magic":mg,"wisdom":ws},
            "rarity":rarity,"alignment":alignment,
            "ability":{"name":ab_name,"description":ab_desc},"description":desc}

def save(slug, figures):
    for i,f in enumerate(figures,1):
        f["id"] = f"{slug}-{i:03d}"
        f["culture_slug"] = slug
    with open(f"{OUT}/{slug}.json","w",encoding="utf-8") as fh:
        json.dump({"culture_slug":slug,"count":len(figures),"figures":figures},fh,indent=2,ensure_ascii=False)
    print(f"  {slug}: {len(figures)} figures")

